Developer-friendly **Mongoose schema design** (normalized + scalable). Minimal explanation, more code.

```javascript
// models/index.js
const mongoose = require("mongoose");
const { Schema } = mongoose;

/* -----------------------------
   COMPANY
-----------------------------*/
const CompanySchema = new Schema({
  name: { type: String, required: true },
  website: String,
  location: String,
  createdAt: { type: Date, default: Date.now }
});

const Company = mongoose.model("Company", CompanySchema);

/* -----------------------------
   PROJECT
-----------------------------*/
const ProjectSchema = new Schema({
  name: { type: String, required: true },
  description: String,
  company: { type: Schema.Types.ObjectId, ref: "Company" },
  techStacks: [String],
  createdAt: { type: Date, default: Date.now }
});

const Project = mongoose.model("Project", ProjectSchema);

/* -----------------------------
   USER
-----------------------------*/
const UserSchema = new Schema({
  name: String,
  email: { type: String, unique: true },
  phone: String,
  companies: [{ type: Schema.Types.ObjectId, ref: "Company" }],
  createdAt: { type: Date, default: Date.now }
});

const User = mongoose.model("User", UserSchema);

/* -----------------------------
   RESUME SUBSCHEMAS
-----------------------------*/

const PersonalInfoSchema = new Schema({
  fullName: String,
  email: String,
  phone: String,
  address: String,
  linkedin: String,
  github: String
}, { _id: false });

const EducationSchema = new Schema({
  degree: String,
  institute: String,
  startYear: Number,
  endYear: Number,
  percentage: Number
}, { _id: false });

const ExperienceSchema = new Schema({
  company: { type: Schema.Types.ObjectId, ref: "Company" },
  designation: String,
  startDate: Date,
  endDate: Date
}, { _id: false });

const ProjectTenureSchema = new Schema({
  project: { type: Schema.Types.ObjectId, ref: "Project" },
  startDate: Date,
  endDate: Date,
  techStacks: [String],
  rolesResponsibilities: [String]
}, { _id: false });

/* -----------------------------
   RESUME
-----------------------------*/

const ResumeSchema = new Schema({

  user: { type: Schema.Types.ObjectId, ref: "User" },

  personalInfo: PersonalInfoSchema,

  experiences: [ExperienceSchema],

  projects: [ProjectTenureSchema],

  education: [EducationSchema],

  techStacks: [String],

  createdAt: { type: Date, default: Date.now }

});

const Resume = mongoose.model("Resume", ResumeSchema);

module.exports = {
  Company,
  Project,
  User,
  Resume
};
```

---

**Example Query (Company → Projects → Users → Resumes)**

```javascript
const companyData = await Company.findById(companyId);

const projects = await Project.find({ company: companyId });

const users = await User.find({ companies: companyId });

const resumes = await Resume.find({
  user: { $in: users.map(u => u._id) }
})
.populate("user")
.populate("experiences.company")
.populate("projects.project");
```

