**Trie (Prefix Tree)** = tree-like DS used for fast **prefix-based search** (strings, autocomplete, dictionary).  
Each node stores children (a–z) + `isEnd` flag.

---

### 1. Basic Trie (Insert, Search, StartsWith 🔥)
```java id="trie1"
class Trie {

    static class Node {
        Node[] children = new Node[26];
        boolean isEnd;
    }

    private Node root;

    public Trie() {
        root = new Node();
    }

    public void insert(String word) {
        Node curr = root;

        for (char c : word.toCharArray()) {
            int idx = c - 'a';

            if (curr.children[idx] == null) {
                curr.children[idx] = new Node();
            }

            curr = curr.children[idx];
        }

        curr.isEnd = true;
    }

    public boolean search(String word) {
        Node node = find(word);
        return node != null && node.isEnd;
    }

    public boolean startsWith(String prefix) {
        return find(prefix) != null;
    }

    private Node find(String s) {
        Node curr = root;

        for (char c : s.toCharArray()) {
            int idx = c - 'a';
            if (curr.children[idx] == null) return null;
            curr = curr.children[idx];
        }

        return curr;
    }
}
```

---

### 2. Trie using HashMap (Flexible charset 🔥)
```java id="trie2"
import java.util.*;

class Trie {

    static class Node {
        Map<Character, Node> children = new HashMap<>();
        boolean isEnd;
    }

    private Node root = new Node();

    public void insert(String word) {
        Node curr = root;

        for (char c : word.toCharArray()) {
            curr.children.putIfAbsent(c, new Node());
            curr = curr.children.get(c);
        }

        curr.isEnd = true;
    }

    public boolean search(String word) {
        Node node = find(word);
        return node != null && node.isEnd;
    }

    public boolean startsWith(String prefix) {
        return find(prefix) != null;
    }

    private Node find(String s) {
        Node curr = root;

        for (char c : s.toCharArray()) {
            if (!curr.children.containsKey(c)) return null;
            curr = curr.children.get(c);
        }

        return curr;
    }
