### 1. DFS + Recursion Stack (Most Important 🔥🔥 O(V+E))
```java id="dc1"
import java.util.*;

public class DirectedCycle {

    static boolean hasCycle(int V, List<List<Integer>> adj) {
        boolean[] visited = new boolean[V];
        boolean[] recStack = new boolean[V];

        for (int i = 0; i < V; i++) {
            if (dfs(i, visited, recStack, adj)) return true;
        }
        return false;
    }

    static boolean dfs(int node, boolean[] visited, boolean[] recStack,
                       List<List<Integer>> adj) {

        if (recStack[node]) return true;
        if (visited[node]) return false;

        visited[node] = true;
        recStack[node] = true;

        for (int nei : adj.get(node)) {
            if (dfs(nei, visited, recStack, adj)) return true;
        }

        recStack[node] = false;
        return false;
    }
}
```

