### 3. Kahn’s Algorithm (BFS Topological Sort 🔥🔥)
```java id="dc3"
import java.util.*;

public class DirectedCycle {

    static boolean hasCycle(int V, List<List<Integer>> adj) {
        int[] indegree = new int[V];

        for (int i = 0; i < V; i++) {
            for (int nei : adj.get(i)) {
                indegree[nei]++;
            }
        }

        Queue<Integer> q = new LinkedList<>();

        for (int i = 0; i < V; i++) {
            if (indegree[i] == 0) q.offer(i);
        }

        int count = 0;

        while (!q.isEmpty()) {
            int node = q.poll();
            count++;

            for (int nei : adj.get(node)) {
                if (--indegree[nei] == 0) {
                    q.offer(nei);
                }
            }
        }

        return count != V; // cycle exists
    }
}
```

