### 4. Iterative DFS (Using Stack 🔥)
```java id="dc4"
import java.util.*;

static boolean hasCycle(int V, List<List<Integer>> adj) {
    int[] color = new int[V];

    for (int i = 0; i < V; i++) {
        if (color[i] != 0) continue;

        Stack<Integer> stack = new Stack<>();
        stack.push(i);

        while (!stack.isEmpty()) {
            int node = stack.peek();

            if (color[node] == 0) {
                color[node] = 1;

                for (int nei : adj.get(node)) {
                    if (color[nei] == 1) return true;
                    if (color[nei] == 0) stack.push(nei);
                }
            } else {
                stack.pop();
                color[node] = 2;
            }
        }
    }

    return false;
}
