```java id="eo1"
class Printer {
    private int num = 1;
    private final int limit;

    Printer(int limit) {
        this.limit = limit;
    }

    public synchronized void printOdd() throws InterruptedException {
        while (num <= limit) {
            if (num % 2 == 0) {
                wait();
            } else {
                System.out.println("Odd: " + num++);
                notify();
            }
        }
    }

    public synchronized void printEven() throws InterruptedException {
        while (num <= limit) {
            if (num % 2 != 0) {
                wait();
            } else {
                System.out.println("Even: " + num++);
                notify();
            }
        }
    }
}

public class Main {
