        Printer printer = new Printer(10);

        Thread t1 = new Thread(() -> {
            try { printer.printOdd(); } catch (Exception e) {}
        });

        Thread t2 = new Thread(() -> {
            try { printer.printEven(); } catch (Exception e) {}
        });

        t1.start();
        t2.start();
    }
}
