Here are **industry-level implementations** of **Heap Sort** 👇

---

### 1. Standard Heap Sort (Max Heap 🔥)
```java id="hs1k9x"
import java.util.*;

public class HeapSort {
    public static void main(String[] args) {
        int[] arr = {4,10,3,5,1};

        heapSort(arr);

        System.out.println(Arrays.toString(arr));
    }

    static void heapSort(int[] arr) {
        int n = arr.length;

        // Build max heap
        for (int i = n / 2 - 1; i >= 0; i--) {
            heapify(arr, n, i);
        }

        // Extract elements
        for (int i = n - 1; i > 0; i--) {
            swap(arr, 0, i);         // move max to end
            heapify(arr, i, 0);      // heapify reduced heap
        }
    }

    static void heapify(int[] arr, int n, int i) {
        int largest = i;
        int left = 2 * i + 1;
        int right = 2 * i + 2;

        if (left < n && arr[left] > arr[largest]) largest = left;
        if (right < n && arr[right] > arr[largest]) largest = right;

        if (largest != i) {
            swap(arr, i, largest);
            heapify(arr, n, largest);
        }
    }

    static void swap(int[] arr, int i, int j) {
        int t = arr[i];
        arr[i] = arr[j];
        arr[j] = t;
    }
}
```

---

### 2. Min Heap Sort (Descending Order)
```java id="hs2p7m"
import java.util.*;

public class HeapSort {
    public static void main(String[] args) {
        int[] arr = {4,10,3,5,1};

        heapSort(arr);

        System.out.println(Arrays.toString(arr));
    }

    static void heapSort(int[] arr) {
        int n = arr.length;

        for (int i = n / 2 - 1; i >= 0; i--) {
            heapify(arr, n, i);
        }

        for (int i = n - 1; i > 0; i--) {
            swap(arr, 0, i);
            heapify(arr, i, 0);
        }
    }

    static void heapify(int[] arr, int n, int i) {
        int smallest = i;
        int l = 2 * i + 1, r = 2 * i + 2;

        if (l < n && arr[l] < arr[smallest]) smallest = l;
        if (r < n && arr[r] < arr[smallest]) smallest = r;

        if (smallest != i) {
            swap(arr, i, smallest);
            heapify(arr, n, smallest);
        }
    }

    static void swap(int[] arr, int i, int j) {
        int t = arr[i];
        arr[i] = arr[j];
        arr[j] = t;
    }
}
