static boolean hasCycle(int n, int[][] edges) {
    DSU dsu = new DSU(n);

    for (int[] e : edges) {
        int u = e[0], v = e[1];

        if (dsu.find(u) == dsu.find(v)) {
            return true;
        }

        dsu.union(u, v);
    }

    return false;
}
