public class LongestPalindrome {
    public static void main(String[] args) {
        String s = "babad";

        int max = 0;

        for (int i = 0; i < s.length(); i++) {
            max = Math.max(max, expand(s, i, i));
            max = Math.max(max, expand(s, i, i + 1));
        }

        System.out.println(max);
