### 2. Kahn’s Algorithm (BFS 🔥🔥 Most Used)
```java id="topo2"
import java.util.*;

public class TopoSortBFS {

    static List<Integer> topoSort(int V, List<List<Integer>> adj) {
        int[] indegree = new int[V];

        for (int i = 0; i < V; i++) {
            for (int nei : adj.get(i)) {
                indegree[nei]++;
            }
        }

        Queue<Integer> q = new LinkedList<>();

        for (int i = 0; i < V; i++) {
            if (indegree[i] == 0) {
                q.offer(i);
            }
        }

        List<Integer> res = new ArrayList<>();

        while (!q.isEmpty()) {
            int node = q.poll();
            res.add(node);

            for (int nei : adj.get(node)) {
                if (--indegree[nei] == 0) {
                    q.offer(nei);
                }
            }
        }

        return res;
    }
}
```

