import java.util.*;

static List<Integer> topoSort(Map<Integer, List<Integer>> graph) {
    Map<Integer, Integer> indegree = new HashMap<>();

    for (int node : graph.keySet()) {
        indegree.putIfAbsent(node, 0);
        for (int nei : graph.get(node)) {
            indegree.put(nei, indegree.getOrDefault(nei, 0) + 1);
        }
    }

    Queue<Integer> q = new LinkedList<>();
    for (int node : indegree.keySet()) {
        if (indegree.get(node) == 0) q.offer(node);
    }

    List<Integer> res = new ArrayList<>();

    while (!q.isEmpty()) {
        int node = q.poll();
        res.add(node);

        for (int nei : graph.getOrDefault(node, new ArrayList<>())) {
            indegree.put(nei, indegree.get(nei) - 1);
            if (indegree.get(nei) == 0) q.offer(nei);
        }
    }

    return res;
}
```

