### 2. Single Stack (Space Optimized 🔥🔥)
```java id="ms2"
import java.util.*;

public class MinStack {
    Stack<Long> stack = new Stack<>();
    long min;

    void push(int x) {
        if (stack.isEmpty()) {
            stack.push(0L);
            min = x;
        } else {
            stack.push(x - min);
            if (x < min) {
                min = x;
            }
        }
    }

    int pop() {
        long diff = stack.pop();

        if (diff < 0) {
            int res = (int) min;
            min = min - diff;
            return res;
        } else {
            return (int) (min + diff);
        }
    }

    int top() {
        long diff = stack.peek();

        if (diff >= 0) return (int) (min + diff);
        else return (int) min;
    }

    int getMin() {
        return (int) min;
    }
}
```

