            int key = arr[i];

            int pos = binarySearch(arr, 0, i - 1, key);

            for (int j = i - 1; j >= pos; j--) {
                arr[j + 1] = arr[j];
            }

            arr[pos] = key;
        }

        System.out.println(Arrays.toString(arr));
    }

    static int binarySearch(int[] arr, int l, int r, int key) {
        while (l <= r) {
            int mid = l + (r - l) / 2;

            if (arr[mid] > key) r = mid - 1;
            else l = mid + 1;
        }
        return l;
    }
}
