### 4. Recursive Insertion Sort
```java id="is4d8q"
import java.util.*;

public class InsertionSort {

    public static void main(String[] args) {
        int[] arr = {5,2,4,6,1,3};

        sort(arr, arr.length);
        System.out.println(Arrays.toString(arr));
    }

    static void sort(int[] arr, int n) {
        if (n <= 1) return;

        sort(arr, n - 1);

        int last = arr[n - 1];
        int j = n - 2;

        while (j >= 0 && arr[j] > last) {
            arr[j + 1] = arr[j];
            j--;
        }

        arr[j + 1] = last;
    }
}
