### 2. Using Length Difference
```java id="ip2"
static Node getIntersection(Node a, Node b) {
    int len1 = length(a), len2 = length(b);

    while (len1 > len2) {
        a = a.next;
        len1--;
    }

    while (len2 > len1) {
        b = b.next;
        len2--;
    }

    while (a != null && b != null) {
        if (a == b) return a;
        a = a.next;
        b = b.next;
    }

    return null;
}

static int length(Node head) {
    int count = 0;
    while (head != null) {
        count++;
        head = head.next;
    }
    return count;
}
