        for (int num : nums) max = Math.max(max, num);

        boolean[] present = new boolean[max + 1];

        for (int num : nums) present[num] = true;

        int longest = 0, current = 0;

        for (int i = 0; i <= max; i++) {
            if (present[i]) {
                current++;
                longest = Math.max(longest, current);
            } else {
                current = 0;
            }
        }

        System.out.println(longest);
    }
}
