### 2. HashSet with Rehashing (Resize 🔥🔥)
```java id="hs2"
import java.util.*;

class MyHashSet<K> {
    private int capacity = 4;
    private int size = 0;
    private List<K>[] buckets;

    MyHashSet() {
        buckets = new LinkedList[capacity];
        for (int i = 0; i < capacity; i++) {
            buckets[i] = new LinkedList<>();
        }
    }

    private int hash(K key) {
        return Math.abs(key.hashCode()) % capacity;
    }

    public void add(K key) {
        int i = hash(key);

        if (!buckets[i].contains(key)) {
            buckets[i].add(key);
            size++;
        }

        if ((double) size / capacity > 0.75) resize();
    }

    private void resize() {
        capacity *= 2;
        List<K>[] old = buckets;

        buckets = new LinkedList[capacity];
        for (int i = 0; i < capacity; i++) {
            buckets[i] = new LinkedList<>();
        }

        size = 0;

        for (List<K> bucket : old) {
            for (K key : bucket) {
                add(key);
            }
        }
    }
}
```

