### 1. Standard QuickSelect (Most Important 🔥)
```java id="qsks1"
import java.util.*;

public class KthSmallest {
    public static void main(String[] args) {
        int[] arr = {7, 10, 4, 3, 20, 15};
        int k = 3; // 3rd smallest

        int result = quickSelect(arr, 0, arr.length - 1, k - 1);
        System.out.println(result);
    }

    static int quickSelect(int[] arr, int low, int high, int k) {
        if (low <= high) {
            int pivot = partition(arr, low, high);

            if (pivot == k) return arr[pivot];
            else if (pivot > k) return quickSelect(arr, low, pivot - 1, k);
            else return quickSelect(arr, pivot + 1, high, k);
        }
        return -1;
    }

    static int partition(int[] arr, int low, int high) {
        int pivot = arr[high];
        int i = low;

        for (int j = low; j < high; j++) {
            if (arr[j] <= pivot) {
                swap(arr, i++, j);
            }
        }

        swap(arr, i, high);
        return i;
    }

    static void swap(int[] arr, int i, int j) {
        int t = arr[i];
        arr[i] = arr[j];
        arr[j] = t;
    }
}
```

