### 2. Random Pivot (Avoid worst case 🔥)
```java id="qsks2"
import java.util.*;

public class KthSmallest {
    static Random rand = new Random();

    public static void main(String[] args) {
        int[] arr = {7,10,4,3,20,15};
        int k = 3;

        System.out.println(select(arr, 0, arr.length - 1, k - 1));
    }

    static int select(int[] arr, int low, int high, int k) {
        if (low == high) return arr[low];

        int pivotIndex = low + rand.nextInt(high - low + 1);
        swap(arr, pivotIndex, high);

        int pi = partition(arr, low, high);

        if (pi == k) return arr[pi];
        else if (pi > k) return select(arr, low, pi - 1, k);
        else return select(arr, pi + 1, high, k);
    }

    static int partition(int[] arr, int low, int high) {
        int pivot = arr[high], i = low;

        for (int j = low; j < high; j++) {
            if (arr[j] <= pivot) {
                swap(arr, i++, j);
            }
        }

        swap(arr, i, high);
        return i;
    }

    static void swap(int[] arr, int i, int j) {
        int t = arr[i];
        arr[i] = arr[j];
        arr[j] = t;
    }
}
