Here are **industry-level ways** to **count inversions in an array** 👇

---

### 1. Merge Sort Approach (Most Important 🔥 O(n log n))
```java id="ci1k9x"
import java.util.*;

public class CountInversions {

    public static void main(String[] args) {
        int[] arr = {2, 4, 1, 3, 5};
        System.out.println(countInversions(arr));
    }

    static int countInversions(int[] arr) {
        return mergeSort(arr, 0, arr.length - 1);
    }

    static int mergeSort(int[] arr, int left, int right) {
        int count = 0;

        if (left < right) {
            int mid = left + (right - left) / 2;

            count += mergeSort(arr, left, mid);
            count += mergeSort(arr, mid + 1, right);
            count += merge(arr, left, mid, right);
        }

        return count;
    }

    static int merge(int[] arr, int left, int mid, int right) {
        int[] temp = new int[right - left + 1];

        int i = left, j = mid + 1, k = 0;
        int count = 0;

        while (i <= mid && j <= right) {
            if (arr[i] <= arr[j]) {
                temp[k++] = arr[i++];
            } else {
                temp[k++] = arr[j++];
                count += (mid - i + 1); // 🔥 key line
            }
        }

        while (i <= mid) temp[k++] = arr[i++];
        while (j <= right) temp[k++] = arr[j++];

        for (int x = 0; x < temp.length; x++) {
            arr[left + x] = temp[x];
        }

        return count;
    }
}
```

---

### 2. Using Single Temp Array (Optimized 🔥)
```java id="ci2p7m"
import java.util.*;

public class CountInversions {

    public static void main(String[] args) {
        int[] arr = {2,4,1,3,5};
        int[] temp = new int[arr.length];

        System.out.println(mergeSort(arr, temp, 0, arr.length - 1));
    }

    static int mergeSort(int[] arr, int[] temp, int l, int r) {
        int count = 0;

        if (l < r) {
            int mid = (l + r) / 2;

            count += mergeSort(arr, temp, l, mid);
            count += mergeSort(arr, temp, mid + 1, r);
            count += merge(arr, temp, l, mid, r);
        }

        return count;
    }

    static int merge(int[] arr, int[] temp, int l, int m, int r) {
        int i = l, j = m + 1, k = l, count = 0;

        while (i <= m && j <= r) {
            if (arr[i] <= arr[j]) temp[k++] = arr[i++];
            else {
                temp[k++] = arr[j++];
                count += (m - i + 1);
            }
        }

        while (i <= m) temp[k++] = arr[i++];
        while (j <= r) temp[k++] = arr[j++];

        for (int x = l; x <= r; x++) arr[x] = temp[x];

        return count;
    }
}
