import java.util.*;

static void postorder(Node root) {
    if (root == null) return;

    Stack<Node> s1 = new Stack<>();
    Stack<Node> s2 = new Stack<>();

    s1.push(root);

    while (!s1.isEmpty()) {
        Node curr = s1.pop();
        s2.push(curr);

        if (curr.left != null) s1.push(curr.left);
        if (curr.right != null) s1.push(curr.right);
