import java.util.*;

static void postorder(Node root) {
    Stack<Node> stack = new Stack<>();
    Node curr = root, lastVisited = null;

    while (curr != null || !stack.isEmpty()) {
        if (curr != null) {
            stack.push(curr);
            curr = curr.left;
        } else {
            Node peek = stack.peek();

            if (peek.right != null && lastVisited != peek.right) {
                curr = peek.right;
            } else {
