### 5. Edge Case Safe Version 🔥
```java id="rm5"
static Node removeNthFromEnd(Node head, int n) {
    if (head == null) return null;

    Node dummy = new Node(0);
    dummy.next = head;

    Node fast = dummy, slow = dummy;

    for (int i = 0; i <= n; i++) {
        if (fast == null) return head; // invalid n
        fast = fast.next;
    }

    while (fast != null) {
        fast = fast.next;
        slow = slow.next;
    }

    if (slow.next != null) {
        slow.next = slow.next.next;
    }

    return dummy.next;
}
```

