Here are **industry-level ways** to **convert a sorted array to a height-balanced BST** 👇

---

### 1. Recursive (Most Important 🔥 O(n))
```java id="arrbst1"
public class SortedArrayToBST {

    static class Node {
        int val;
        Node left, right;
        Node(int v) { val = v; }
    }

    static Node sortedArrayToBST(int[] nums) {
        return build(nums, 0, nums.length - 1);
    }

    static Node build(int[] nums, int l, int r) {
        if (l > r) return null;

        int mid = l + (r - l) / 2;

        Node root = new Node(nums[mid]);
        root.left = build(nums, l, mid - 1);
        root.right = build(nums, mid + 1, r);

        return root;
    }
}
```

---

### 2. Iterative using Queue 🔥🔥
```java id="arrbst2"
import java.util.*;

public class SortedArrayToBST {

    static class Node {
        int val;
        Node left, right;
        Node(int v) { val = v; }
    }

    static class Pair {
        int l, r;
        Node node;

        Pair(int l, int r, Node n) {
            this.l = l;
            this.r = r;
            this.node = n;
        }
    }

    static Node sortedArrayToBST(int[] nums) {
        if (nums.length == 0) return null;

        int mid = nums.length / 2;
        Node root = new Node(nums[mid]);

        Queue<Pair> q = new LinkedList<>();
        q.offer(new Pair(0, nums.length - 1, root));

        while (!q.isEmpty()) {
            Pair p = q.poll();
            int l = p.l, r = p.r;
            Node node = p.node;

            int m = l + (r - l) / 2;

            if (l <= m - 1) {
                int leftMid = l + (m - 1 - l) / 2;
                node.left = new Node(nums[leftMid]);
                q.offer(new Pair(l, m - 1, node.left));
            }

            if (m + 1 <= r) {
                int rightMid = m + 1 + (r - (m + 1)) / 2;
                node.right = new Node(nums[rightMid]);
                q.offer(new Pair(m + 1, r, node.right));
            }
        }

        return root;
    }
}
```

---

### 3. Always Choose Right Mid (Variation 🔥)
```java id="arrbst3"
static Node build(int[] nums, int l, int r) {
