### 3. Morris Traversal (O(1) Space 🔥🔥🔥)
```java id="in3"
static void inorder(Node root) {
    Node curr = root;

    while (curr != null) {
        if (curr.left == null) {
            System.out.print(curr.val + " ");
            curr = curr.right;
        } else {
            Node pred = curr.left;

            while (pred.right != null && pred.right != curr) {
                pred = pred.right;
            }

            if (pred.right == null) {
                pred.right = curr; // thread
                curr = curr.left;
            } else {
                pred.right = null; // remove thread
                System.out.print(curr.val + " ");
                curr = curr.right;
            }
        }
    }
}
