### 2. Pop Costly
```java id="sq2"
import java.util.*;

public class StackUsingQueues {
    Queue<Integer> q1 = new LinkedList<>();
    Queue<Integer> q2 = new LinkedList<>();

    void push(int x) {
        q1.offer(x);
    }

    int pop() {
        if (q1.isEmpty()) throw new RuntimeException("Empty");

        while (q1.size() > 1) {
            q2.offer(q1.poll());
        }

        int val = q1.poll();

        // swap queues
        Queue<Integer> temp = q1;
        q1 = q2;
        q2 = temp;

        return val;
    }

    int top() {
        if (q1.isEmpty()) throw new RuntimeException("Empty");

        while (q1.size() > 1) {
            q2.offer(q1.poll());
        }

        int val = q1.peek();
        q2.offer(q1.poll());

        Queue<Integer> temp = q1;
        q1 = q2;
        q2 = temp;

        return val;
    }

    public static void main(String[] args) {
        StackUsingQueues s = new StackUsingQueues();

        s.push(1);
        s.push(2);

        System.out.println(s.top()); // 2
        System.out.println(s.pop()); // 2
    }
}
```

