```java id="ma4d8q"
import java.util.*;

public class MergeArrays {
    public static void main(String[] args) {
        int[] a = {1,4,7,8,10};
        int[] b = {2,3,9};

        int n = a.length, m = b.length;

        for (int gap = (n + m + 1) / 2; gap > 0; gap = (gap == 1 ? 0 : (gap + 1) / 2)) {
            int i = 0, j = gap;

            while (j < n + m) {
                int aVal = get(a, b, i, n);
                int bVal = get(a, b, j, n);

                if (aVal > bVal) {
                    set(a, b, i, bVal, n);
                    set(a, b, j, aVal, n);
                }

                i++; j++;
            }
        }

        System.out.println(Arrays.toString(a));
        System.out.println(Arrays.toString(b));
    }

    static int get(int[] a, int[] b, int i, int n) {
        return (i < n) ? a[i] : b[i - n];
    }

    static void set(int[] a, int[] b, int i, int val, int n) {
        if (i < n) a[i] = val;
        else b[i - n] = val;
    }
}
