public class StackArray {
    int[] arr;
    int top;

    StackArray() {
        arr = new int[2];
        top = -1;
    }

    void push(int x) {
        if (top == arr.length - 1) resize();
        arr[++top] = x;
    }

    int pop() {
        if (top == -1) throw new RuntimeException("Empty stack");
        return arr[top--];
    }

    int peek() {
        if (top == -1) throw new RuntimeException("Empty stack");
        return arr[top];
    }

    void resize() {
        arr = Arrays.copyOf(arr, arr.length * 2);
    }

