### 1. Dutch National Flag Algorithm (Best 🔥 O(n), O(1))
```java id="dnf1k9x"
import java.util.*;

public class Sort012 {
    public static void main(String[] args) {
        int[] arr = {2,0,2,1,1,0};

        int low = 0, mid = 0, high = arr.length - 1;

        while (mid <= high) {
            if (arr[mid] == 0) {
                swap(arr, low++, mid++);
            } else if (arr[mid] == 1) {
                mid++;
            } else {
                swap(arr, mid, high--);
            }
        }

        System.out.println(Arrays.toString(arr));
    }

    static void swap(int[] arr, int i, int j) {
        int temp = arr[i];
        arr[i] = arr[j];
        arr[j] = temp;
    }
}
```

