Here are **industry-level implementations** to **detect cycle using Union-Find (DSU)** 👇

---

### 1. Basic Cycle Detection (Undirected Graph 🔥)
```java id="ufc1"
class DSU {
    int[] parent;

    DSU(int n) {
        parent = new int[n];
        for (int i = 0; i < n; i++) parent[i] = i;
    }

    int find(int x) {
        if (parent[x] == x) return x;
        return find(parent[x]);
    }

    void union(int a, int b) {
        int pa = find(a);
        int pb = find(b);

        if (pa != pb) {
            parent[pb] = pa;
        }
    }
}

static boolean hasCycle(int n, int[][] edges) {
    DSU dsu = new DSU(n);

    for (int[] e : edges) {
        int u = e[0], v = e[1];

        if (dsu.find(u) == dsu.find(v)) {
            return true; // cycle found
        }

        dsu.union(u, v);
    }

    return false;
}
```

---

### 2. Optimized (Path Compression + Rank 🔥🔥)
```java id="ufc2"
class DSU {
    int[] parent, rank;

    DSU(int n) {
        parent = new int[n];
        rank = new int[n];

        for (int i = 0; i < n; i++) parent[i] = i;
    }

    int find(int x) {
        if (parent[x] != x)
            parent[x] = find(parent[x]);
        return parent[x];
    }

    boolean union(int a, int b) {
        int pa = find(a);
        int pb = find(b);

        if (pa == pb) return false; // cycle

        if (rank[pa] < rank[pb]) {
            parent[pa] = pb;
        } else if (rank[pa] > rank[pb]) {
            parent[pb] = pa;
        } else {
            parent[pb] = pa;
            rank[pa]++;
        }

        return true;
    }
}

static boolean hasCycle(int n, int[][] edges) {
    DSU dsu = new DSU(n);

    for (int[] e : edges) {
        if (!dsu.union(e[0], e[1])) {
            return true;
        }
    }

    return false;
}
```

