import java.util.*;

static Node merge(Node l1, Node l2) {
    PriorityQueue<Node> pq = new PriorityQueue<>(
        (a, b) -> a.val - b.val
    );

    if (l1 != null) pq.add(l1);
    if (l2 != null) pq.add(l2);

    Node dummy = new Node(0), tail = dummy;

    while (!pq.isEmpty()) {
        Node node = pq.poll();
        tail.next = node;
        tail = tail.next;

        if (node.next != null) pq.add(node.next);
    }

    return dummy.next;
}
