import java.util.*;

public class QueueArray {
    int[] arr;
    int front, rear, size;

    QueueArray() {
        arr = new int[2];
        front = 0;
        rear = 0;
        size = 0;
    }

    void enqueue(int x) {
        if (size == arr.length) resize();

        arr[rear++] = x;
        size++;
    }

    int dequeue() {
        if (size == 0) throw new RuntimeException("Empty");

        int val = arr[front++];
        size--;
        return val;
    }

    void resize() {
        arr = Arrays.copyOfRange(arr, front, rear + arr.length);
        rear = size;
        front = 0;
    }

    public static void main(String[] args) {
        QueueArray q = new QueueArray();

        q.enqueue(1);
        q.enqueue(2);
        q.enqueue(3); // resize

        System.out.println(q.dequeue());
    }
}
