### 1. DFS (Most Common 🔥)
```java id="fl1"
public class FlattenList {

    static class Node {
        int val;
        Node next, child;

        Node(int v) { val = v; }
    }

    static Node flatten(Node head) {
        if (head == null) return null;

        Node curr = head;

        while (curr != null) {
            if (curr.child != null) {
                Node next = curr.next;

                Node childTail = flatten(curr.child);

                curr.next = curr.child;
                curr.child = null;

                Node temp = curr.next;
                while (temp.next != null) temp = temp.next;

                temp.next = next;
            }
            curr = curr.next;
        }

        return head;
    }
}
