### 2. Iterative Using Stack 🔥🔥
```java id="fl2"
import java.util.*;

public class FlattenList {

    static class Node {
        int val;
        Node next, child;
        Node(int v) { val = v; }
    }

    static Node flatten(Node head) {
        if (head == null) return null;

        Stack<Node> stack = new Stack<>();
        Node curr = head;

        while (curr != null) {
            if (curr.child != null) {
                if (curr.next != null) {
                    stack.push(curr.next);
                }

                curr.next = curr.child;
                curr.child = null;
            }

            if (curr.next == null && !stack.isEmpty()) {
                curr.next = stack.pop();
            }

            curr = curr.next;
        }

        return head;
    }
}
