### 1. Min Heap (Basic Priority Queue 🔥)
```java id="pq1"
import java.util.*;

public class MinHeap {
    int[] heap;
    int size;

    MinHeap(int capacity) {
        heap = new int[capacity];
        size = 0;
    }

    void insert(int val) {
        heap[size] = val;
        int i = size++;

        while (i > 0 && heap[parent(i)] > heap[i]) {
            swap(i, parent(i));
            i = parent(i);
        }
    }

    int extractMin() {
        if (size == 0) throw new RuntimeException("Empty");

        int root = heap[0];
        heap[0] = heap[--size];

        heapify(0);
        return root;
    }

    void heapify(int i) {
        int smallest = i;
        int l = left(i), r = right(i);

