### 2. Iterative (Best for interviews 🔥🔥)
```java id="kg2"
public class ReverseKGroup {

    static class Node {
        int val;
        Node next;
        Node(int v) { val = v; }
    }

    static Node reverseKGroup(Node head, int k) {
        Node dummy = new Node(0);
        dummy.next = head;

        Node prevGroup = dummy;

        while (true) {
            Node kth = getKth(prevGroup, k);
            if (kth == null) break;

            Node nextGroup = kth.next;

            // reverse group
            Node prev = nextGroup;
            Node curr = prevGroup.next;

            while (curr != nextGroup) {
                Node temp = curr.next;
                curr.next = prev;
                prev = curr;
                curr = temp;
            }

            Node temp = prevGroup.next;
            prevGroup.next = kth;
            prevGroup = temp;
        }

        return dummy.next;
    }

    static Node getKth(Node curr, int k) {
        while (curr != null && k-- > 0) {
            curr = curr.next;
        }
        return curr;
    }
}
```

