```java id="md5n3w"
public class MedianOfTwoArrays {
    public static void main(String[] args) {
        int[] a = {};
        int[] b = {1};

        if (a.length == 0) {
            System.out.println(b[b.length/2]);
            return;
        }

        if (b.length == 0) {
            System.out.println(a[a.length/2]);
            return;
        }

        System.out.println(findMedian(a, b));
    }

    static double findMedian(int[] a, int[] b) {
        if (a.length > b.length) return findMedian(b, a);

        int low = 0, high = a.length;

        while (low <= high) {
            int cut1 = (low + high)/2;
            int cut2 = (a.length + b.length + 1)/2 - cut1;

            int l1 = (cut1==0)?Integer.MIN_VALUE:a[cut1-1];
            int l2 = (cut2==0)?Integer.MIN_VALUE:b[cut2-1];
            int r1 = (cut1==a.length)?Integer.MAX_VALUE:a[cut1];
            int r2 = (cut2==b.length)?Integer.MAX_VALUE:b[cut2];

            if(l1<=r2 && l2<=r1){
                if((a.length+b.length)%2==0)
                    return (Math.max(l1,l2)+Math.min(r1,r2))/2.0;
                else
                    return Math.max(l1,l2);
            }
            else if(l1>r2) high=cut1-1;
            else low=cut1+1;
        }
        return 0;
    }
