package com.prem.wikimedia;

import com.launchdarkly.eventsource.EventHandler;
import com.launchdarkly.eventsource.EventSource;
import okhttp3.Headers;

import java.net.URI;
import java.util.concurrent.TimeUnit;

public class WikimediaStreamClient {

    public static void main(String[] args) throws Exception {

        String streamUrl = "https://stream.wikimedia.org/v2/stream/recentchange";

        EventHandler handler = new WikimediaEventHandler();

        EventSource.Builder builder = new EventSource.Builder(handler, URI.create(streamUrl))
                .reconnectTimeMs(3000) // auto reconnect
                .headers(Headers.of("Accept", "text/event-stream"));

        EventSource eventSource = builder.build();

        eventSource.start();

        // keep app alive
        TimeUnit.MINUTES.sleep(10);
    }
}
