## 🎯 4. Wikimedia Event Handler

```java
package com.prem.wikimedia.handler;

import com.fasterxml.jackson.databind.JsonNode;
import com.fasterxml.jackson.databind.ObjectMapper;
import com.launchdarkly.eventsource.EventHandler;
import com.launchdarkly.eventsource.MessageEvent;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import org.springframework.kafka.core.KafkaTemplate;

public class WikimediaChangesHandler implements EventHandler {

    private static final Logger log =
            LoggerFactory.getLogger(WikimediaChangesHandler.class);

    private final KafkaTemplate<String, String> kafkaTemplate;
    private final String topic;
    private final ObjectMapper mapper = new ObjectMapper();

    public WikimediaChangesHandler(KafkaTemplate<String, String> kafkaTemplate,
                                   String topic) {
        this.kafkaTemplate = kafkaTemplate;
        this.topic = topic;
    }

    @Override
    public void onOpen() {
        log.info("✅ Connected to Wikimedia stream");
    }

    @Override
    public void onClosed() {
        log.warn("❌ Stream closed");
    }

    @Override
    public void onMessage(String event, MessageEvent messageEvent) {
        try {
            String data = messageEvent.getData();
            JsonNode json = mapper.readTree(data);

            // 🔥 Filter only edit events
            if ("edit".equals(json.get("type").asText())) {

                kafkaTemplate.send(topic, data)
                        .whenComplete((res, ex) -> {
                            if (ex == null) {
                                log.info("✅ Sent to Kafka offset={}",
                                        res.getRecordMetadata().offset());
                            } else {
                                log.error("❌ Kafka error", ex);
                            }
                        });
            }

        } catch (Exception e) {
            log.error("Parsing error", e);
        }
    }

    @Override
    public void onComment(String comment) {}

    @Override
    public void onError(Throwable t) {
        log.error("⚠️ Error", t);
    }
}
```

