package com.prem.wikimedia.service;

import com.launchdarkly.eventsource.EventSource;
import com.prem.wikimedia.handler.WikimediaChangesHandler;
import jakarta.annotation.PostConstruct;
import okhttp3.Headers;
import org.springframework.beans.factory.annotation.Value;
import org.springframework.kafka.core.KafkaTemplate;
import org.springframework.stereotype.Service;

import java.net.URI;

@Service
public class WikimediaStreamService {

    private final KafkaTemplate<String, String> kafkaTemplate;

    @Value("${wikimedia.stream-url}")
    private String streamUrl;

    @Value("${wikimedia.topic}")
    private String topic;

    public WikimediaStreamService(KafkaTemplate<String, String> kafkaTemplate) {
        this.kafkaTemplate = kafkaTemplate;
    }

    @PostConstruct
    public void startStream() {

        WikimediaChangesHandler handler =
                new WikimediaChangesHandler(kafkaTemplate, topic);

        EventSource.Builder builder =
                new EventSource.Builder(handler, URI.create(streamUrl))
                        .headers(Headers.of("Accept", "text/event-stream"))
                        .reconnectTimeMs(3000);

        EventSource eventSource = builder.build();
        eventSource.start();
    }
}
