```java
package com.prem.springboot;

import com.launchdarkly.eventsource.EventHandler;
import com.launchdarkly.eventsource.MessageEvent;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import org.springframework.kafka.core.KafkaTemplate;

public class WikimediaChangesHandler implements EventHandler {

    private static final Logger logger =
            LoggerFactory.getLogger(WikimediaChangesHandler.class);

    private final KafkaTemplate<String, String> kafkaTemplate;
    private final String topic;

    public WikimediaChangesHandler(KafkaTemplate<String, String> kafkaTemplate,
                                   String topic) {
        this.kafkaTemplate = kafkaTemplate;
        this.topic = topic;
    }

    @Override
    public void onOpen() {
        logger.info("✅ Connection opened to Wikimedia stream");
    }

    @Override
    public void onClosed() {
        logger.warn("❌ Connection closed");
    }

    @Override
    public void onMessage(String event, MessageEvent messageEvent) {
        String data = messageEvent.getData();

        logger.info("📩 Event Received: {}", event);
        logger.debug("Payload: {}", data);

        // 🔥 Send to Kafka (async)
        kafkaTemplate.send(topic, data)
                .whenComplete((result, ex) -> {
                    if (ex == null) {
                        logger.info("✅ Sent to Kafka topic={}, offset={}",
                                topic,
                                result.getRecordMetadata().offset());
                    } else {
                        logger.error("❌ Kafka send failed", ex);
                    }
                });
    }

    @Override
    public void onComment(String comment) {
        // ignore
    }

    @Override
    public void onError(Throwable t) {
        logger.error("⚠️ Error in EventSource", t);
    }
}
```

