## 🚀 1. Stock Streaming API (1 sec)

### `server.js`
```js id="stock-stream-server"
const express = require('express');
const cors = require('cors');

const app = express();
app.use(cors());

const PORT = 3000;

// Initial stock data
let stocks = [
    { symbol: 'RELIANCE', price: 2500 },
    { symbol: 'TCS', price: 3800 },
    { symbol: 'INFY', price: 1500 },
    { symbol: 'HDFCBANK', price: 1650 },
    { symbol: 'ICICIBANK', price: 950 }
];

// Random price fluctuation
const updatePrices = () => {
    return stocks.map(stock => {
        let change = (Math.random() * 10 - 5).toFixed(2); // -5 to +5
        let newPrice = (stock.price + parseFloat(change)).toFixed(2);

        return {
            symbol: stock.symbol,
            price: parseFloat(newPrice),
            change: parseFloat(change),
            time: new Date().toISOString()
        };
    });
};

// SSE Endpoint
app.get('/stream-stocks', (req, res) => {
    res.setHeader('Content-Type', 'text/event-stream');
    res.setHeader('Cache-Control', 'no-cache');
    res.setHeader('Connection', 'keep-alive');

    console.log('Client connected to stock stream');

    const interval = setInterval(() => {
        const updatedData = updatePrices();
        stocks = updatedData.map(s => ({ symbol: s.symbol, price: s.price }));

        res.write(`data: ${JSON.stringify(updatedData)}\n\n`);
    }, 1000);

    req.on('close', () => {
        console.log('Client disconnected');
        clearInterval(interval);
    });
});

app.listen(PORT, () => {
    console.log(`Stock server running at http://localhost:${PORT}`);
});
```

