## 🚀 5. Kafka Producer (Stock Generator 🔥)

### `StockProducer.java`
```java
package com.prem.stock;

import org.springframework.kafka.core.KafkaTemplate;
import org.springframework.stereotype.Service;

import java.util.*;
import java.util.concurrent.ThreadLocalRandom;

@Service
public class StockProducer {

    private final KafkaTemplate<String, Object> kafkaTemplate;

    public StockProducer(KafkaTemplate<String, Object> kafkaTemplate) {
        this.kafkaTemplate = kafkaTemplate;
    }

    private Map<String, Double> stockPrices = new HashMap<>();

    {
        stockPrices.put("RELIANCE", 2500.0);
        stockPrices.put("TCS", 3800.0);
        stockPrices.put("INFY", 1500.0);
        stockPrices.put("HDFCBANK", 1650.0);
    }

    public void generateAndSend() {
        List<Stock> updates = new ArrayList<>();

        for (String symbol : stockPrices.keySet()) {
            double oldPrice = stockPrices.get(symbol);
            double change = ThreadLocalRandom.current().nextDouble(-5, 5);
            double newPrice = oldPrice + change;

            stockPrices.put(symbol, newPrice);

            updates.add(new Stock(
                    symbol,
                    Math.round(newPrice * 100.0) / 100.0,
                    Math.round(change * 100.0) / 100.0,
                    System.currentTimeMillis()
            ));
        }

        kafkaTemplate.send("stock-topic", updates);
    }
}
```

