## 🧑‍💻 3. Fast Read API (Redis First 🚀)

```js
// getOrder.js
const Redis = require("ioredis");
const redis = new Redis();

const fakeDB = []; // same DB reference assume

const getOrder = async (orderId) => {
  // 👉 1. Check Redis
  const cached = await redis.get(`order:${orderId}`);

  if (cached) {
    console.log("From Redis 🚀");
    return JSON.parse(cached);
  }

  // 👉 2. Fallback DB
  const order = fakeDB.find(o => o.orderId === orderId);

  if (order) {
    await redis.set(`order:${orderId}`, JSON.stringify(order));
  }

  console.log("From DB 🐢");
  return order;
};

// Example
getOrder("ORD123").then(console.log);
