# 🔥 7. Kafka Consumer (DB + Redis)

```java
package com.prem.kafka;

import com.fasterxml.jackson.databind.ObjectMapper;
import com.prem.dto.OrderEvent;
import com.prem.entity.Order;
import com.prem.repository.OrderRepository;
import org.springframework.data.redis.core.RedisTemplate;
import org.springframework.kafka.annotation.KafkaListener;
import org.springframework.stereotype.Service;

@Service
public class OrderConsumer {

    private final OrderRepository repo;
    private final RedisTemplate<String, Object> redisTemplate;

    public OrderConsumer(OrderRepository repo, RedisTemplate<String, Object> redisTemplate) {
        this.repo = repo;
        this.redisTemplate = redisTemplate;
    }

    @KafkaListener(topics = "order-topic", groupId = "order-group")
    public void consume(OrderEvent event) {

        // 👉 Save to DB
        Order order = new Order(
                event.getOrderId(),
                event.getUserId(),
                event.getAmount()
        );

        repo.save(order);

        // 👉 Cache in Redis
        redisTemplate.opsForValue()
                .set("order:" + order.getOrderId(), order);
    }
}
```

