# 🌐 9. Service Layer (Cache First)

```java
package com.prem.service;

import com.prem.entity.Order;
import com.prem.repository.OrderRepository;
import org.springframework.data.redis.core.RedisTemplate;
import org.springframework.stereotype.Service;

@Service
public class OrderService {

    private final RedisTemplate<String, Object> redisTemplate;
    private final OrderRepository repo;

    public OrderService(RedisTemplate<String, Object> redisTemplate, OrderRepository repo) {
        this.redisTemplate = redisTemplate;
        this.repo = repo;
    }

    public Order getOrder(String orderId) {

        // 👉 Redis
        Object cached = redisTemplate.opsForValue().get("order:" + orderId);
        if (cached != null) {
            return (Order) cached;
        }

        // 👉 DB fallback
        Order order = repo.findById(orderId).orElse(null);

        if (order != null) {
            redisTemplate.opsForValue().set("order:" + orderId, order);
        }

        return order;
    }
}
```

