## 🚀 3. Consumer Group (Production pattern 🔥)

```js
// consumer-group.js
const { createClient } = require('redis');

(async () => {
  const client = createClient();
  await client.connect();

  const streamKey = 'mystream';
  const group = 'mygroup';
  const consumer = 'consumer-1';

  // create group (ignore error if exists)
  try {
    await client.xGroupCreate(streamKey, group, '0', { MKSTREAM: true });
  } catch (e) {}

  while (true) {
    const response = await client.xReadGroup(
      group,
      consumer,
      [{ key: streamKey, id: '>' }],
      { BLOCK: 5000, COUNT: 10 }
    );

    if (response) {
      for (const stream of response) {
        for (const msg of stream.messages) {
          console.log('Processing:', msg.id, msg.message);

          // ACK after processing
          await client.xAck(streamKey, group, msg.id);
        }
      }
    }
  }
})();
```

