## 🚀 Consumer Group (Best Practice 🔥)

```js
// consumer-group.js
import { createClient } from 'redis';

const client = createClient();

const STREAM = 'mystream';
const GROUP = 'group1';
const CONSUMER = 'consumer1';

async function initGroup() {
  try {
    await client.xGroupCreate(STREAM, GROUP, '0', { MKSTREAM: true });
    console.log('Group created');
  } catch (e) {
    if (!e.message.includes('BUSYGROUP')) throw e;
  }
}

async function startConsumerGroup() {
  await client.connect();
  await initGroup();

  while (true) {
    const data = await client.xReadGroup(
      GROUP,
      CONSUMER,
      [{ key: STREAM, id: '>' }],
      { BLOCK: 5000, COUNT: 10 }
    );

    if (!data) continue;

    for (const s of data) {
      for (const msg of s.messages) {
        console.log('Processing ->', msg.id, msg.message);

        // simulate work
        await new Promise(r => setTimeout(r, 500));

        await client.xAck(STREAM, GROUP, msg.id);
      }
    }
  }
}

startConsumerGroup().catch(console.error);
```

