## 🔥 Consumer (Reliable + Retry + DLQ)

```java id="cons1"
import com.fasterxml.jackson.databind.ObjectMapper;
import jakarta.annotation.PostConstruct;
import org.springframework.beans.factory.annotation.Value;
import org.springframework.data.redis.core.RedisTemplate;
import org.springframework.stereotype.Service;

@Service
public class JobConsumer {

    private final RedisTemplate<String, String> redisTemplate;
    private final ObjectMapper mapper = new ObjectMapper();

    @Value("${app.queue.main}")
    private String mainQueue;

    @Value("${app.queue.processing}")
    private String processingQueue;

    @Value("${app.queue.dlq}")
    private String dlqQueue;

    @Value("${app.queue.max-retry}")
    private int maxRetry;

    public JobConsumer(RedisTemplate<String, String> redisTemplate) {
        this.redisTemplate = redisTemplate;
    }

    @PostConstruct
    public void start() {
        new Thread(this::consume).start();
    }

    private void consume() {
        while (true) {
            try {
                // move job → processing
                String json = redisTemplate.opsForList()
                        .rightPopAndLeftPush(mainQueue, processingQueue);

                if (json == null) {
                    Thread.sleep(1000);
                    continue;
                }

                Job job = mapper.readValue(json, Job.class);

                try {
                    process(job);

                    // success → remove from processing
                    redisTemplate.opsForList().remove(processingQueue, 1, json);

                } catch (Exception ex) {
                    handleFailure(job, json);
                }

            } catch (Exception e) {
                e.printStackTrace();
            }
        }
    }

    private void process(Job job) throws Exception {
        System.out.println("Processing: " + job);

        // simulate failure
        if (Math.random() < 0.5) {
            throw new RuntimeException("Random failure");
        }
    }

    private void handleFailure(Job job, String json) throws Exception {
        job.setRetryCount(job.getRetryCount() + 1);

        if (job.getRetryCount() > maxRetry) {
            // send to DLQ
            redisTemplate.opsForList().leftPush(dlqQueue,
                    mapper.writeValueAsString(job));

            redisTemplate.opsForList().remove(processingQueue, 1, json);

            System.out.println("Moved to DLQ: " + job);

        } else {
            // retry → push back to main queue
            redisTemplate.opsForList().leftPush(mainQueue,
                    mapper.writeValueAsString(job));

            redisTemplate.opsForList().remove(processingQueue, 1, json);

            System.out.println("Retrying: " + job);
        }
    }
}
```

