```js
// stream-processor.js (Kafka Streams alternative 😎)
const { Kafka } = require("kafkajs");

const kafka = new Kafka({ brokers: ["localhost:9092"] });

const consumer = kafka.consumer({ groupId: "stock-group" });
const producer = kafka.producer();

const window = {}; // in-memory state

async function run() {
  await consumer.connect();
  await producer.connect();

  await consumer.subscribe({ topic: "stock-prices" });

  await consumer.run({
    eachMessage: async ({ message }) => {
      const [stock, price] = message.value.toString().split(",");
      const p = parseFloat(price);

      if (!window[stock]) window[stock] = [];
      window[stock].push(p);

      // last 5 values window
      if (window[stock].length > 5) window[stock].shift();

      const avg =
        window[stock].reduce((a, b) => a + b, 0) /
        window[stock].length;

      await producer.send({
        topic: "processed-prices",
        messages: [
          { key: stock, value: `${stock},AVG:${avg.toFixed(2)}` },
        ],
      });
    },
  });
}

run();
```

