## 🚀 Consumer Code (Batch of 10)

```js
const { Kafka } = require('kafkajs');

const kafka = new Kafka({
  clientId: 'weather-consumer',
  brokers: ['localhost:9092'],
});

const consumer = kafka.consumer({ groupId: 'weather-group' });

const BATCH_SIZE = 10;
let buffer = [];

// 🔥 Simulated DB save
async function saveToDB(records) {
  console.log(`Saving batch of ${records.length} records...`);
  console.log(records);
  // TODO: replace with Mongo / Postgres insertMany
}

async function flush() {
  if (buffer.length > 0) {
    await saveToDB(buffer);
    buffer = [];
  }
}

async function run() {
  await consumer.connect();
  await consumer.subscribe({ topic: 'weather-report', fromBeginning: false });

  await consumer.run({
    eachMessage: async ({ message }) => {
      const value = JSON.parse(message.value.toString());

      buffer.push(value);

      if (buffer.length >= BATCH_SIZE) {
        await flush();
      }
    },
  });

  // 🔥 periodic flush (important if <10 messages come)
  setInterval(async () => {
    await flush();
  }, 5000);
}

run().catch(console.error);
```

