## 🔥 Advanced Enhancements

```js
// retry wrapper
async function saveWithRetry(records, retries = 3) {
  try {
    await saveToDB(records);
  } catch (err) {
    if (retries > 0) {
      console.log("Retrying...");
      await saveWithRetry(records, retries - 1);
    } else {
      console.error("Send to DLQ", records);
      // produce to DLQ topic
    }
  }
}
```

