# 🔥 Batch Consumer (IMPORTANT)

```java
@Service
@RequiredArgsConstructor
public class WeatherConsumer {

    private final WeatherRepository repository;
    private final RedisTemplate<String, Object> redisTemplate;

    private final List<WeatherDocument> buffer = new ArrayList<>();
    private final int BATCH_SIZE = 10;

    @KafkaListener(topics = "weather-report", containerFactory = "kafkaListenerContainerFactory")
    public void consume(List<WeatherEvent> events, Acknowledgment ack) {

        for (WeatherEvent event : events) {

            WeatherDocument doc = new WeatherDocument();
            doc.setCity(event.getCity());
            doc.setTemp(event.getTemp());
            doc.setHumidity(event.getHumidity());
            doc.setTimestamp(event.getTimestamp());

            buffer.add(doc);

            if (buffer.size() >= BATCH_SIZE) {
                flush();
            }
        }

        ack.acknowledge();
    }

    private void flush() {
        try {
            repository.saveAll(buffer);

            // cache latest
            for (WeatherDocument doc : buffer) {
                redisTemplate.opsForValue()
                        .set("weather:" + doc.getCity(), doc);
            }

            buffer.clear();

        } catch (Exception e) {
            // DLQ fallback
            System.out.println("Error → Send to DLQ");
        }
    }
}
```

