# ⚙️ Kafka Batch Config

```java
@Configuration
public class KafkaConfig {

    @Bean
    public ConcurrentKafkaListenerContainerFactory<String, WeatherEvent> kafkaListenerContainerFactory(
            ConsumerFactory<String, WeatherEvent> consumerFactory) {

        ConcurrentKafkaListenerContainerFactory<String, WeatherEvent> factory =
                new ConcurrentKafkaListenerContainerFactory<>();

        factory.setConsumerFactory(consumerFactory);

        factory.setBatchListener(true); // 🔥 important
        factory.getContainerProperties().setAckMode(ContainerProperties.AckMode.MANUAL);

        return factory;
    }
}
