# 🚀 Consumer (Batch + Retry + DLQ + Redis)

```js
// consumer/consumer.js
const kafka = require('../shared/kafka');
const { connectDB, saveBatch } = require('./db');
const { cacheWeather } = require('./redis');
const { sendToDLQ } = require('./dlqProducer');

const consumer = kafka.consumer({ groupId: 'weather-group' });

const BATCH_SIZE = 10;
let buffer = [];

async function saveWithRetry(records, retries = 3) {
  try {
    await saveBatch(records);

    // cache latest
    for (let r of records) {
      await cacheWeather(r);
    }

  } catch (err) {
    if (retries > 0) {
      return saveWithRetry(records, retries - 1);
    } else {
      console.error("DLQ:", records);
      await sendToDLQ(records);
    }
  }
}

async function flush() {
  if (buffer.length === 0) return;

  const batch = [...buffer];
  buffer = [];

  await saveWithRetry(batch);
}

async function run() {
  await connectDB();
  await consumer.connect();

  await consumer.subscribe({ topic: 'weather-report' });

  await consumer.run({
    eachMessage: async ({ message }) => {
      const data = JSON.parse(message.value.toString());

      buffer.push(data);

      if (buffer.length >= BATCH_SIZE) {
        await flush();
      }
    },
  });

  // ⏱️ flush every 5 sec
  setInterval(flush, 5000);
}

run();
```

