import { useEffect, useState } from "react";
import API from "../api";
import { useParams } from "react-router-dom";

export default function Documents() {
  const { db, col } = useParams();
  const [docs, setDocs] = useState([]);
  const [json, setJson] = useState("{}");

  const load = () => {
    API.get(`/documents/${db}/${col}`).then(res => setDocs(res.data));
  };

  useEffect(() => {
    load();
  }, []);

  const insert = async () => {
    await API.post(`/documents/${db}/${col}`, JSON.parse(json));
    load();
  };

  const del = async (id) => {
    await API.delete(`/documents/${db}/${col}/${id}`);
    load();
  };

  return (
    <div>
      <h2>{db} / {col}</h2>

      <textarea
        rows={5}
        value={json}
        onChange={e => setJson(e.target.value)}
      />

      <button onClick={insert}>Insert</button>

      <hr />

      {docs.map(d => (
        <div key={d._id}>
          <pre>{JSON.stringify(d, null, 2)}</pre>
          <button onClick={() => del(d._id)}>Delete</button>
        </div>
      ))}
    </div>
  );
}
